{"file_path":"src/addr.js","content":"export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}

// Returns {col,row,name} or null when outside the addressable range.
export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  return { col: colIndex(L), row, name: L + row }
}

export function addrKey(a) {
  return a.col * 1000 + a.row
}
"}

{"file_path":"src/parse.js","content":"// Parses a formula body; returns an AST or null when the grammar rejects it.
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('syntax') }
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const CMP = ['=', '<>', '<=', '>=', '<', '>']

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-')) { p++; return { k: 'neg', e: unary() } }
    if (isOp('+')) { p++; return { k: 'pos', e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.t === 'num') return { k: 'num', v: t.v }
    if (t.t === 'op' && t.v === '(') {
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.t !== 'word') fail()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { k: 'call', name: t.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') fail()
      return { k: 'range', a: t.v, b: toks[p++].v }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE') return { k: 'bool', v: true }
    if (u === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', name: t.v }
  }

  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}
"}

