{"file_path":"src/parse.js","content":"// Parses a formula body; returns an AST or null when the grammar rejects it.
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('syntax') }
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const CMP = ['=', '<>', '<=', '>=', '<', '>']

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-')) { p++; return { k: 'neg', e: unary() } }
    if (isOp('+')) { p++; return { k: 'pos', e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.t === 'num') return { k: 'num', v: t.v }
    if (t.t === 'op' && t.v === '(') {
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.t !== 'word') fail()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { k: 'call', name: t.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') fail()
      return { k: 'range', a: t.v, b: toks[p++].v }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE') return { k: 'bool', v: true }
    if (u === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', name: t.v }
  }

  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddr, addrKey } from './addr.js'

const ERR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })
const rank = { n: 0, s: 1, b: 2 }

function cpCompare(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  format(v) {
    if (v.t === 'e' || v.t === 's') return v.v
    if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
    return String(Number(v.v.toPrecision(10)))
  }

  get(a) {
    const key = addrKey(a)
    if (this.memo.has(key)) return this.memo.get(key)
    const c = this.cells.get(key)
    if (!c) return num(0)
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    let v
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      v = ast ? this.ev(ast) : err('#ERR!')
    } else v = this.literal(c.content)
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  literal(s) {
    if (s === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
    if (ERR_TOKENS.has(s)) return err(s)
    return { t: 's', v: s }
  }

  // Number reading of a non-error value.
  toNum(v) {
    if (v.t === 'n') return num(v.v)
    if (v.t === 'b') return num(v.v ? 1 : 0)
    return err('#VALUE!')
  }

  finite(x) {
    return Number.isFinite(x) ? num(x) : err('#DIV/0!')
  }

  // Values contributed by one argument; ranges expand.
  argValues(n) {
    if (n.k !== 'range') return [this.ev(n)]
    const a = parseAddr(n.a)
    const b = parseAddr(n.b)
    if (!a || !b) return [err('#REF!')]
    const out = []
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
      for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
        const v = this.get({ col: c, row: r })
        out.push(v)
        if (v.t === 'e') return out
      }
    return out
  }

  scalar(n) {
    if (n.k !== 'range') return this.ev(n)
    const vs = this.argValues(n)
    const e = vs.find((v) => v.t === 'e')
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#ERR!')
  }

  ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'range': return err('#ERR!')
      case 'ref': {
        const a = parseAddr(n.name)
        return a ? this.get(a) : err('#REF!')
      }
      case 'neg':
      case 'pos': {
        const v = this.ev(n.e)
        if (v.t === 'e') return v
        const x = this.toNum(v)
        if (x.t === 'e') return x
        return num(n.k === 'neg' ? -x.v : x.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.t === 'e') return l
    const r = this.ev(n.r)
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      let d
      if (l.t !== r.t) d = rank[l.t] - rank[r.t]
      else if (l.t === 's') d = cpCompare(l.v, r.v)
      else d = Number(l.v) - Number(r.v)
      if (l.t === r.t && l.t !== 's') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = this.toNum(l)
    const b = this.toNum(r)
    if (a.t === 'e') return a
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return this.finite(a.v + b.v)
      case '-': return this.finite(a.v - b.v)
      case '*': return this.finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : this.finite(a.v / b.v)
      case '^': return this.finite(Math.pow(a.v, b.v))
    }
    return err('#ERR!')
  }

  call(n) {
    const k = n.args.length
    const name = n.name
    if (name === 'IF') {
      if (k !== 3) return err('#ERR!')
      const c = this.scalar(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return this.scalar(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (k !== 1) return err('#ERR!')
      const v = this.scalar(n.args[0])
      if (v.t === 'e') return v
      const x = this.toNum(v)
      return x.t === 'e' ? x : num(Math.abs(x.v))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (k < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) {
      for (const v of this.argValues(a)) {
        if (v.t === 'e') return v
        vals.push(v)
      }
    }
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const xs = []
    for (const v of vals) {
      const x = this.toNum(v)
      if (x.t === 'e') return x
      xs.push(x.v)
    }
    if (name === 'SUM') return this.finite(xs.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return this.finite(xs.reduce((s, x) => s + x, 0) / xs.length)
    if (name === 'MIN') return num(Math.min(...xs))
    return num(Math.max(...xs))
  }
}
"}

